preflight.query:
query IndependentCaGbContextPreflight($caMarket: ID!, $gbMarket: ID!, $variantIds: [ID!]!) {
  caMarket: market(id: $caMarket) {
    id name status
    currencySettings { baseCurrency { currencyCode } localCurrencies }
    catalogs(first: 20) { nodes { id status publication { id } } pageInfo { hasNextPage endCursor } }
    conditions { regionsCondition { regions(first: 100) { nodes { id name } pageInfo { hasNextPage endCursor } } } }
  }
  gbMarket: market(id: $gbMarket) {
    id name status
    currencySettings { baseCurrency { currencyCode } localCurrencies }
    catalogs(first: 20) { nodes { id status publication { id } } pageInfo { hasNextPage endCursor } }
    conditions { regionsCondition { regions(first: 100) { nodes { id name } pageInfo { hasNextPage endCursor } } } }
  }
  variants: nodes(ids: $variantIds) {
    ... on ProductVariant {
      id product { id }
      ca: contextualPricing(context: { country: CA }) { price { amount currencyCode } }
      gb: contextualPricing(context: { country: GB }) { price { amount currencyCode } }
    }
  }
}
